import{state,JOIN_OPS}from "../../js/core/state.js";import{getPair}from "../../js/core/utils.js";export function generateSql(){const currentOp=state.currentOp;const opConfig=JOIN_OPS[currentOp];if(!opConfig){const [li,ri]=getPair();const leftTable=state.tables[li];const rightTable=state.tables[ri];const hasData=leftTable?.rows?.length > 0 && rightTable?.rows?.length > 0;if(hasData){return "--Select an operation to see SQL";}return "--Add data to your tables first";}if(opConfig.group==="join"){return generateJoinSql();}else if(opConfig.group==="set"){return generateSetOpSql();}return "--Unknown operation";}function buildOnClause(li,ri){const leftTable=state.tables[li];const rightTable=state.tables[ri];const validConditions=state.joinConditions.filter((c)=> c && c.leftCol && c.rightCol);if(validConditions.length===0)return "";const conditions=validConditions.map((cond)=>{const leftCol=leftTable.columns.find((c)=> c.id===cond.leftCol);const rightCol=rightTable.columns.find((c)=> c.id===cond.rightCol);if(!leftCol || !rightCol)return null;return `${leftTable.name}.${leftCol.name}${cond.op || "="}${rightTable.name}.${rightCol.name}`;}).filter(Boolean);return conditions.join(" AND ");}function buildSelfJoinOnClause(li){const leftTable=state.tables[li];const validConditions=state.joinConditions.filter((c)=> c && c.leftCol && c.rightCol);if(validConditions.length===0)return "";const conditions=validConditions.map((cond)=>{const leftCol=leftTable.columns.find((c)=> c.id===cond.leftCol);const rightCol=leftTable.columns.find((c)=> c.id===cond.rightCol);if(!leftCol || !rightCol)return null;return `${leftTable.name}.${leftCol.name}${cond.op || "="}t2.${rightCol.name}`;}).filter(Boolean);return conditions.join(" AND ");}function generateJoinSql(){const [li,ri]=getPair();const leftTable=state.tables[li];const rightTable=state.tables[ri];if(!leftTable || !rightTable){return "--Add tables to generate SQL";}const opName=getJoinKeyword();const selectCols=[ ...leftTable.columns.map((c)=> `${leftTable.name}.${c.name}`),...rightTable.columns.map((c)=> `${rightTable.name}.${c.name}`),];let sql=`SELECT ${selectCols[0]}\n`;if(selectCols.length > 1){sql=`SELECT ${selectCols[0]},\n `+selectCols.slice(1).join(",\n ")+"\n";}sql+=`FROM ${leftTable.name}\n`;if(state.currentOp==="cross"){sql+=`CROSS JOIN ${rightTable.name}`;}else if(state.currentOp==="self"){sql=`--SELF JOIN is not a SQL keyword. It's implemented using INNER JOIN with a table alias.\n`+sql;sql+=`INNER JOIN ${leftTable.name}AS t2`;const onClause=buildSelfJoinOnClause(li);if(onClause){sql+=`\nON ${onClause}`;}}else if(state.currentOp.includes("anti")|| state.currentOp.includes("semi")){const keyword=state.currentOp==="left_anti" || state.currentOp==="left_semi" ? "LEFT":"RIGHT";const joinType=state.currentOp.includes("anti")&& !state.currentOp.includes("semi")? "ANTI":"SEMI";sql+=`${keyword}${joinType}JOIN ${rightTable.name}`;const onClause=buildOnClause(li,ri);if(onClause){sql+=`\nON ${onClause}`;}}else if(state.currentOp==="exists" || state.currentOp==="not_exists"){const keyword=state.currentOp==="not_exists" ? "NOT EXISTS":"EXISTS";const leftCols=leftTable.columns.map((c)=> `${leftTable.name}.${c.name}`);sql=`SELECT ${leftCols.join(",\n ")}`;sql+=`\nFROM ${leftTable.name}\nWHERE ${keyword}(\n SELECT 1\n FROM ${rightTable.name}`;const onClause=buildOnClause(li,ri);if(onClause){sql+=`\n WHERE ${onClause}`;}sql+="\n);";return sql;}else{sql+=`${opName}${rightTable.name}`;const onClause=buildOnClause(li,ri);if(onClause){sql+=`\nON ${onClause}`;}}sql+=";";return sql;}function generateSetOpSql(){const [li,ri]=getPair();const leftTable=state.tables[li];const rightTable=state.tables[ri];if(!leftTable || !rightTable){return "--Add tables to generate SQL";}const opKeyword=getSetOpKeyword();const leftColIds=leftTable.columns.map(c=> c.id);const rightColIds=rightTable.columns.map(c=> c.id);const allColIds=[...new Set([...leftColIds,...rightColIds])];const leftSelect=allColIds.map(colId=>{const col=leftTable.columns.find(c=> c.id===colId);return col ? col.name:"NULL";}).join(",\n ");const rightSelect=allColIds.map(colId=>{const leftCol=leftTable.columns.find(c=> c.id===colId);const rightCol=rightTable.columns.find(c=> c.id===colId);const colName=leftCol ? leftCol.name:"col_"+colId;if(rightCol){return `${rightCol.name}AS ${colName}`;}return `NULL AS ${colName}`;}).join(",\n ");const sql=`SELECT ${leftSelect}\nFROM ${leftTable.name}\n`+`${opKeyword}\n`+`SELECT ${rightSelect}\nFROM ${rightTable.name};`;return sql;}function getJoinKeyword(){const keywords={inner:"INNER JOIN",left:"LEFT OUTER JOIN",right:"RIGHT OUTER JOIN",full:"FULL OUTER JOIN",};return keywords[state.currentOp] || "INNER JOIN";}function getSetOpKeyword(){const keywords={union:"UNION",union_all:"UNION ALL",except:"EXCEPT",intersect:"INTERSECT",};return keywords[state.currentOp] || "UNION";}export function copySqlToClipboard(sql){navigator.clipboard.writeText(sql).then(()=>{const btn=document.getElementById("sql-copy-btn");if(btn){const originalText=btn.textContent;btn.textContent="Copied!";setTimeout(()=>{btn.textContent=originalText;},2000);}},(err)=>{console.error("Failed to copy:",err);},);}function highlightSql(sql){let escaped=sql .replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");const commentPlaceholders=[];let commentIndex=0;escaped=escaped.replace(/(--[^\n]*)|(\/\*[\s\S]*?\*\/)/g,(match)=>{commentPlaceholders.push(match);return `__COMMENT_${commentIndex++}__`;});escaped=escaped.replace(/('(?:[^'\\]|\\.)*')/g,'<span class="sql-string">$1</span>');escaped=escaped.replace(/\b(\d+(?:\.\d+)?)\b/g,'<span class="sql-number">$1</span>');const functions=/\b(COUNT|SUM|AVG|MIN|MAX|COALESCE|NULLIF|IFNULL|CAST|CONVERT|UPPER|LOWER|LENGTH|TRIM|ROUND|FLOOR|CEIL|ABS|CAST|CONCAT|SUBSTRING|COALESCE|NULLIF)\b/gi;escaped=escaped.replace(functions,'<span class="sql-function">$1</span>');const keywords=/\b(SELECT|FROM|WHERE|JOIN|INNER|LEFT|RIGHT|FULL|OUTER|ON|CROSS|UNION|EXCEPT|INTERSECT|EXISTS|AS|AND|OR|NOT|ORDER|BY|GROUP|HAVING|LIMIT|OFFSET|ALL|DISTINCT|NULL|IS|IN|LIKE|BETWEEN|CASE|WHEN|THEN|ELSE|END)\b/gi;escaped=escaped.replace(keywords,'<span class="sql-keyword">$1</span>');escaped=escaped.replace(/__COMMENT_(\d+)__/g,(match,index)=>{return `<span class="sql-comment">${commentPlaceholders[parseInt(index)]}</span>`;});return escaped;}export function renderSqlPanel(){try{const sql=generateSql();const panel=document.getElementById("sql-panel");if(!panel)return;const codeBlock=panel.querySelector("pre code");if(codeBlock){try{codeBlock.innerHTML=highlightSql(sql);}catch(highlightErr){console.error("Error highlighting SQL:",highlightErr);codeBlock.textContent=sql;}}const [li,ri]=getPair();const leftTable=state.tables[li];const rightTable=state.tables[ri];if(leftTable && rightTable && leftTable.rows.length > 0 && rightTable.rows.length > 0){panel.style.display="block";}else{panel.style.display="none";}}catch(err){console.error("[Error] renderSqlPanel failed:",err);const panel=document.getElementById("sql-panel");const codeBlock=panel?.querySelector("pre code");if(codeBlock){codeBlock.textContent="--Error generating SQL. Please check your data.";}}}